CustomField.formula:
if(Category_Sales_Mail_Active__c=false && Category_Sales_Mail_Active__c=false, " * No Mail: 0pts", "No Mail: 0pts")&BR()&

if(First_Sales_Mail_Ordered_Date__c<Date(Year(Budget_Month_Date__c), Month(Budget_Month_Date__c),1), 
	"**Mail Ordered Before 1st of the Budget Month = 10pts**", 
	"Mail Ordered Before 1st of the Budget Month = 10pts")&BR()&
if(First_Sales_Mail_Ordered_Date__c>Date(Year(Budget_Month_Date__c), Month(Budget_Month_Date__c),1) && First_Sales_Mail_Ordered_Date__c<Date(Year(Budget_Month_Date__c), Month(Budget_Month_Date__c),7), 
	"**Mail Ordered Before 7th of the Budget Month = 7pts**", 
	"Mail Ordered Before 7th of the Budget Month = 7pts")&BR()&
if(First_Sales_Mail_Ordered_Date__c>Date(Year(Budget_Month_Date__c), Month(Budget_Month_Date__c),7), 
	"**Mail Ordered After 7th of the Budget Month = 3pts**", 
	"Mail Ordered After 7th of the Budget Month = 3pts")
	&BR()&BR()&
if(Category_Service_Mail_Active__c,
	"**Service Mail = +5pts**", 
	"Service Mail = +5pts")&BR()&
if(Category_Service_Mail_Active__c=false,	
	"**No Service Mail = +0pts**",
	"No Service Mail = +0pts"
)
